int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;
    MOVDataRef *dref;

    if (!c->nb_streams) {
        avio_skip(pb, atom.size);
        return 0;
    }

    entries = avio_rb32(pb); // Read number of entries
    if (!entries) {
        avio_skip(pb, atom.size - 4);
        return 0;
    }

    if (!(dref = av_mallocz(entries * sizeof(MOVDataRef)))) {
        return AVERROR(ENOMEM);
    }

    for (i = 0; i < entries; i++) {
        int size = avio_rb32(pb);
        if (size < 12) {
            av_freep(&dref);
            avio_skip(pb, atom.size - 4 - 4 * i);
            return AVERROR_INVALIDDATA;
        }

        dref[i].type = avio_rl32(pb);
        avio_skip(pb, 4); // Reserved

        if (dref[i].type == MKTAG('a','l','i','a')) {
            // Handle Macintosh alias records
            int alias_size = avio_rb38(pb);
            if (alias_size > size - 12) {
                av_freep(&dref);
                return AVERROR_INVALIDDATA;
            }
            dref[i].data = av_malloc(alias_size);
            avio_read(pb, dref[i].data, alias_size);
        } else if (dref[i].type == MKTAG('u','r','l',' ')) {
            // Handle URL type
            int flags = avio_rb16(pb);
            dref[i].filename = av_malloc(size - 12);
            avio_read(pb, dref[i].filename, size - 12);
        } else {
            // Generic handling
            dref[i].data = av_malloc(size - 12);
            avio_read(pb, dref[i].data, size - 12);
        }
    }

    c->data_refs = dref;
    c->nb_data_refs = entries;

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;

    if (!c->nb_streams) {
        return AVERROR_INVALIDDATA;
    }

    entries = avio_rb32(pb); // number of entries
    if (entries < 0) {
        return entries;
    }

    for (i = 0; i < entries; i++) {
        char type[5];
        int size;
        uint32_t flags;

        size = avio_rb32(pb);
        if (size < 0) {
            return size;
        }

        avio_read(pb, type, 4);
        type[4] = 0;
        avio_skip(pb, 4); // handler

        if (!strcmp(type, "alis")) {
            avio_rb32(pb); // alias data size
            avio_skip(pb, 4); // padding
            avio_skip(pb, 4); // flags

            avio_skip(pb, 4); // volume
            avio_skip(pb, 4); // dirid
            avio_skip(pb, 4); // dircount

            avio_skip(pb, 4); // name length
            avio_skip(pb, 256); // name

            avio_skip(pb, 4); // path type
            avio_skip(pb, 4); // path length
            avio_skip(pb, 1024); // path
        } else {
            avio_skip(pb, size - 12);
        }
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;
    MOVTrack *track;
    int size;

    if (!c->pb || url_feof(c->pb))
        return AVERROR_EOF;

    size = atom.size;
    if (size < 8)
        return AVERROR_INVALIDDATA;

    avio_r8(pb); // version
    avio_r8(pb); // flags

    entries = avio_rb32(pb);
    if (!entries)
        return 0;

    if (entries < 0 || entries > (size - 8))
        return AVERROR_INVALIDDATA;

    for (i = 0; i < entries; i++) {
        int type;
        int len;

        type = avio_rl32(pb);
        len  = avio_rb32(pb);
        if (len < 0 || len > (size - 8 - avio_tell(pb)))
            return AVERROR_INVALIDDATA;

        switch (type) {
        case MKTAG('u','r','l',' '):
            if (len < 1)
                return AVERROR_INVALIDDATA;
            avio_skip(pb, 1);
            len -= 1;
            break;
        case MKTAG('a','l','i','a'):
            break;
        default:
            avio_skip(pb, len);
            continue;
        }

        avio_skip(pb, len);
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;
    int size;

    if (!c->nb_streams) {
        avio_skip(pb, atom.size);
        return 0;
    }

    entries = avio_rb32(pb);
    if (entries < 0)
        return AVERROR_INVALIDDATA;

    for (i = 0; i < entries; i++) {
        int type;
        int len;
        char *filename = NULL;
        char *path = NULL;
        int volume;

        len = avio_rb32(pb);
        type = avio_rl32(pb);

        switch (type) {
            case MKTAG('u', 'r', 'l', ' '):
                volume = avio_get_byte(pb);
                avio_skip(pb, 1);
                size = avio_rb16(pb);
                filename = av_malloc(size + 1);
                if (!filename)
                    return AVERROR(ENOMEM);
                avio_get_str(pb, size, filename, size + 1);
                break;
            case MKTAG('a', 'l', 'i', 'a'):
                volume = avio_get_byte(pb);
                avio_skip(pb, 1);
                size = avio_rb16(pb);
                path = av_malloc(size + 1);
                if (!path)
                    return AVERROR(ENOMEM);
                avio_read(pb, path, size);
                path[size] = 0;
                break;
            default:
                avio_skip(pb, len - 4);
                continue;
        }

        // Assume we need to process the data further here.
        av_freep(&filename);
        av_freep(&path);
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i, j;
    uint32_t entries, size, type;
    uint16_t version;
    uint8_t flags[3];
    uint16_t vol;
    char *filename = NULL;
    char *path = NULL;
    int ret = 0;

    if (!c->nb_streams) {
        return AVERROR_INVALIDDATA;
    }

    version = avio_r8(pb);
    avio_read(pb, flags, 3);

    entries = avio_rb32(pb);

    if (entries > UINT_MAX / sizeof(*c->dref)) {
        ret = AVERROR_INVALIDDATA;
        goto fail;
    }

    c->dref = av_malloc(entries * sizeof(*c->dref));
    if (!c->dref) {
        ret = AVERROR(ENOMEM);
        goto fail;
    }

    for (i = 0; i < entries; i++) {
        size = avio_rb32(pb);
        type = avio_rb32(pb);

        if (type == MKTAG('a','l','i','a')) {
            // Macintosh alias record
            int alias_size;
            alias_size = avio_rb32(pb);
            avio_skip(pb, alias_size - 4);
        } else if (type == MKTAG('f','r','e','s')) {
            // File reference
            avio_skip(pb, 1);
            vol = avio_rb16(pb);
            filename = av_malloc(size - 12);
            if (!filename) {
                ret = AVERROR(ENOMEM);
                goto fail;
            }
            avio_read(pb, filename, size - 12);
            path = av_malloc(size - 12);
            if (!path) {
                ret = AVERROR(ENOMEM);
                goto fail;
            }
            for (j = 0; j < size - 12; j++) {
                path[j] = filename[j];
            }
            c->dref[i].type = type;
            c->dref[i].filename = filename;
            c->dref[i].path = path;
        } else {
            avio_skip(pb, size - 8);
        }
    }

    return 0;

fail:
    av_freep(&c->dref);
    av_freep(&filename);
    av_freep(&path);
    return ret;
}
